// Synthetic ground truth is only read by the evaluator, never by either model.
// Times are seconds after the start of each independent stream.
const chat=(id,name,split,lines)=>({id,name,split,messages:lines.map(([at,speaker,text,expected,extra={}],index)=>({
  id:`${id}-${index}`,at,viewerId:`eval-viewer-${speaker}`,name:`Chatter${speaker}`,text,expected,
  ...extra,...(extra.parent!==undefined?{parentId:`${id}-${extra.parent}`}:{})}))});

